head.script:
scwin.init = function() {
    var jsonData = [{
            'col2': "autoFitFilterList is True autoFitFilterList is True",
            'col3': "1"
        },
        {
            'col2': "sample001",
            'col3': "2"
        },
        {
            'col2': "sample002",
            'col3': "3"
        },
        {
            'col2': "sample002",
            'col3': "4"
        },
        {
            'col2': "sample002",
            'col3': "5"
        }
    ];
    dataList1.setJSON(jsonData);
};
scwin.gridView1_onviewchange = function(info) {
    var col = dataList1.getColumnID(info.colIndex);
    if (col == "col3") {
        gridView1.setCellChecked(info.rowIndex, "col1", true);
    }
    txta.setValue(JSON.stringify(dataList1.getAllJSON()));
};
scwin.grid1_ongroupby = function(options) {
    options.closeGroup = true;
    options.groupbyHeader = [{
        inputType: 'expression',
        expression: 'toggle() + depthStr() + "    [ " + count() + " 건 ]  "',
        align: 'left',
        colSpan: 5
    }];
    options.groupbyFooter = [{
        inputType: 'expression',
        expression: 'SUM("col3")'
    }];
    this.groupby(options);
    //				return false;
    //				return true;
}
scwin.gridView1_oncellclick = function(row, col) {
    console.log(gridView1.getFocusedRowIndex());
    console.log(dataList1.getCellData(gridView1.getFocusedRowIndex(), 'col3'));
};
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function() {
    scwin.simulateWrapper('#gridView1_column3', 'drag-n-drop', {
        dx: -10,
        dy: -50
    });
}
scwin.checkVal1 = function() {
    return WebSquare.wUnit.getJq('#gridView1_cell_0_0').text() == 'autoFitFilterList is True autoFitFilterList is True    [ 1 건 ]  ';
}
scwin.checkVal2 = function() {
    return WebSquare.wUnit.getJq('#gridView1_cell_2_0').text() == 'sample001    [ 1 건 ]  ';
}
scwin.checkVal3 = function() {
    return WebSquare.wUnit.getJq('#gridView1_cell_4_0').text() == 'sample002    [ 3 건 ]  ';
}
scwin.checkVal4 = function() {
    return WebSquare.wUnit.getJq('#gridView1_groupbyZone_list').width() >= WebSquare.wUnit.getJq('.w2grid_groupbyZone_list_listRow:nth-child(3) span').width();
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 1. 샘플실행 후 'name2'항목을 groupby 시킨다.
    //1. After executing the sample, groupby the 'name2' item.
    //Verify step 1. The 'name2' item is groupby.
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.w2grid_groupbyZone_column').length == 1", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.w2grid_groupbyZone_column_value').text() == 'name2'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal3()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 'name2'항목을 클릭하여 filterList의 내용이 모두 보여지는지 확인한다.
    //2. Click on the 'name2' item to see if all the contents of the filterList are visible.
    //Verify step 2. The contents of the FilterList are shown without truncation.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2grid_groupbyZone_column').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal4()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.init();
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 30-Mar-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
